create or replace function priv.t_app_upd() returns trigger language plpgsql security definer set search_path to 'pg_catalog','api' as $f$
declare o int; n int; lim numeric; used numeric;
begin
  o:=priv.ord(old.status_id); n:=priv.ord(new.status_id);
  if n is null then raise exception 'unknown status' using errcode='23514'; end if;
  if n<>o and not ((o<3 and n=o+1) or (o=3 and n in (4,5))) then
    raise exception 'status transition not allowed' using errcode='23514'; end if;
  if n in (4,5) and coalesce(btrim(new.verdict),'')='' then
    raise exception 'verdict required to approve/reject' using errcode='23514'; end if;
  if n=4 and (o<>4 or new.amount is distinct from old.amount or new.company_id is distinct from old.company_id) then
    select funding_limit into lim from api.company where id=new.company_id for update;
    if lim is null then raise exception 'amount exceeds company limit' using errcode='23514'; end if;
    select coalesce(sum(a.amount),0) into used from api.application a
      where a.company_id=new.company_id and a.id<>new.id and priv.ord(a.status_id)=4;
    if new.amount > lim - used then
      raise exception 'amount exceeds company limit minus approved' using errcode='23514'; end if;
  end if;
  return new;
end $f$;
